-- Темы 01–04: исправлены странности в 45 вопросах (125 исправлений), прежние версии в question_archive (миграция 111), ключи не меняются.
-- Источник: scripts/questions/112_oddities_topics01_04.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Какая утилита непосредственно создаёт файлы нового кластера баз данных?', NULL, NULL, NULL, 'Нужно инициализировать пустой кластер, без копирования существующего. Какая утилита сама создаст его системные базы и конфигурационные файлы?'),
        ('question', 'Кто не может быть владельцем каталога нового кластера?', NULL, NULL, NULL, 'От имени какого пользователя ОС нельзя запускать initdb и сервер PostgreSQL?'),
        ('question', 'В каком порядке выполняются скрипты настройки при запуске psql?', NULL, NULL, NULL, 'psql запущен без -X, пути и имена файлов настройки не переопределены. Системный psqlrc и пользовательский ~/.psqlrc существуют и доступны для чтения. Как psql обработает эти файлы?'),
        ('question', 'Параметр задан в файлах конфигурации несколько раз. Какое значение применится?', NULL, NULL, NULL, 'В исправных файлах конфигурации один параметр задан несколько раз. Какое из этих назначений имеет приоритет при чтении файлов?'),
        ('question', 'Сколько действует значение, установленное командой SET LOCAL?', NULL, NULL, NULL, 'В сеансе открыли явную транзакцию и выполнили SET LOCAL. Настройку больше не меняют, ROLLBACK TO не выполняют. До какого момента действует заданное значение?'),
        ('question', 'Какая библиотека является стандартной реализацией клиент-серверного протокола PostgreSQL?', NULL, NULL, NULL, 'Приложению на C нужна клиентская библиотека из стандартной поставки PostgreSQL для подключения и отправки запросов. Что выбрать?'),
        ('question', 'Что означает свойство транзакций «атомарность»?', NULL, NULL, NULL, 'Транзакция перевода денег меняет два баланса. Какую гарантию её итоговому результату даёт атомарность?'),
        ('question', 'Где размещаются разобранные запросы, состояние курсоров и место для сортировок?', NULL, NULL, NULL, 'В какой области оперативной памяти хранятся разобранные запросы, состояние курсоров и рабочие буферы непараллельной сортировки?'),
        ('question', 'Когда стоит использовать менеджер пула соединений, например pgBouncer?', NULL, NULL, NULL, 'В какой ситуации пул соединений, например pgBouncer, поможет сократить затраты на создание backend-процессов?'),
        ('question', 'Что обязательно нужно для обычной сборки PostgreSQL 16 из релизного архива на Unix/Linux с помощью configure и GNU make, без дополнительных процедурных языков и тестов?', NULL, NULL, NULL, 'Собираете PostgreSQL 16 из официального релизного архива на Unix/Linux способом с configure. Дополнительные языки и тесты не нужны, необязательные библиотеки разрешено отключать. Какие два компонента из списка необходимы?'),
        ('question', 'Допишите настройку, чтобы приглашение имело вид пользователь@база=#:
```
\set PROMPT1 ''___%/%R%x%# ''
```', NULL, NULL, NULL, 'Допишите PROMPT1, чтобы перед именем базы появились имя пользователя сеанса и знак @; признаки состояния подключения и транзакции сохраните:
```
\set PROMPT1 ''___%/%R%x%# ''
```'),
        ('question', 'Почему для сборки из репозитория git нужны Flex и Bison, а для сборки из архива с исходными кодами нет?', NULL, NULL, NULL, 'Почему для сборки неизменённых исходников из Git нужны Flex и Bison, а из официального релизного архива PostgreSQL 16 — нет?'),
        ('question', 'Что верно для PostgreSQL как управляемого сервиса у облачного провайдера (DBaaS, «база данных как услуга»)?', NULL, NULL, NULL, 'Вы используете типичный управляемый PostgreSQL у облачного провайдера, без доступа к ОС сервера. Какие два утверждения об администрировании верны?'),
        ('question', 'Какими командами можно выйти из psql?', NULL, NULL, NULL, 'Вы работаете в интерактивном psql, буфер запроса пуст. Какие две команды, введённые отдельно, завершат psql?'),
        ('question', 'Какие команды psql меняют формат вывода результатов запросов?', NULL, NULL, NULL, 'Какие три метакоманды psql предназначены для управления форматом вывода? Нужные аргументы, где они требуются, будут переданы.'),
        ('question', 'Как psql по умолчанию выполняет команды SQL с точки зрения транзакций?', NULL, NULL, NULL, 'В интерактивном psql включён AUTOCOMMIT. Явная транзакция не открыта, SQL-команды отправляют по одной. Как фиксируются успешно выполненные команды?'),
        ('question', 'Какие языки программирования для подпрограмм входят в стандартную поставку PostgreSQL?', NULL, NULL, NULL, 'Какие процедурные языки поставляются с исходным кодом PostgreSQL 16, хотя для некоторых нужна отдельная поддержка при сборке?'),
        ('question', 'Что такое пользовательская функция в PostgreSQL?', NULL, NULL, NULL, 'Расчёт нужно выполнять на сервере и вызывать из выражения SELECT с аргументами. Какой объект для этого создать?'),
        ('question', 'В базе определена функция app.add_tax(numeric), возвращающая numeric. Что делает запрос SELECT app.add_tax(100);?', NULL, NULL, NULL, 'Есть функция app.add_tax(numeric), возвращающая numeric. Что можно сказать о запросе SELECT app.add_tax(100); без чтения тела функции?'),
        ('question', 'Какие формы результата может иметь пользовательская функция PostgreSQL при соответствующем объявлении?', NULL, NULL, NULL, 'Объявляете функцию для вызова из SQL. Какие две формы результата можно задать? Возврат ссылок на курсоры не рассматриваем.'),
        ('question', 'На обычной несекционированной таблице есть один включённый триггер AFTER UPDATE FOR EACH ROW без WHEN (не CONSTRAINT-триггер), его функция не выполняет действий, вызывающих повторное срабатывание. Одна команда UPDATE изменила 10 строк, других триггеров нет. Сколько раз он сработает к завершению этой команды?', NULL, NULL, NULL, 'На несекционированной таблице включён один триггер AFTER UPDATE FOR EACH ROW, без WHEN. Это обычный, не CONSTRAINT-триггер. Других триггеров нет, его функция лишь выдаёт сообщение и возвращает NEW. UPDATE успешно изменил 10 строк. Сколько раз вызовется функция до завершения команды?'),
        ('question', 'На email создан обычный уникальный индекс без условия WHERE. Что произойдёт при попытке вставить вторую строку с тем же ненулевым email обычным INSERT без ON CONFLICT, если триггеры не изменяют и не отменяют вставляемую строку?', NULL, NULL, NULL, 'На таблице users успешно создан индекс:
```
CREATE UNIQUE INDEX users_email_uq ON users(email);
```
Строка с email = ''user@example.org'' уже зафиксирована и другими транзакциями не изменяется. Триггеров нет. Что произойдёт при INSERT ещё одной строки с таким email, без ON CONFLICT?'),
        ('question', 'Какие варианты индексов поддерживает PostgreSQL?', NULL, NULL, NULL, 'Какие из этих индексов можно создать в PostgreSQL 16?'),
        ('question', 'В Debian/Ubuntu psql запускается через штатный pg_wrapper. Локальные кластеры принимают TCP-подключения на 127.0.0.1, доступ роли postgres к базе postgres разрешён; переменные окружения не переопределяют подключение. Какие две команды выберут кластер 16/trainrepl при таком выводе pg_lsclusters?
```
Ver Cluster   Port Status
16  main      5432 online
16  trainrepl 5434 online,recovery
17  main      5433 online
```', NULL, NULL, NULL, 'Нужно подключиться к кластеру 16/trainrepl из вывода pg_lsclusters ниже. Система — Debian/Ubuntu со штатным pg_wrapper. Кластеры принимают TCP-подключения на 127.0.0.1. Роли postgres разрешён вход в базу postgres. Переменные окружения не переопределяют подключение. Какие две команды подходят?
```
Ver Cluster   Port Status
16  main      5432 online
16  trainrepl 5434 online,recovery
17  main      5433 online
```'),
        ('question', 'Сравнивают два независимых запуска команд. Перед каждым запуском вне транзакции установлено work_mem = 8MB. После приведённых команд в первом запуске выполняют COMMIT, во втором — ROLLBACK; других изменений настройки нет. Какие значения покажет SHOW work_mem после завершения транзакции в первом и втором случаях?
```
BEGIN;
SET work_mem = ''32MB'';
SET LOCAL work_mem = ''64MB'';
```', NULL, NULL, NULL, 'В двух отдельных сеансах исходное work_mem равно 8MB. В каждом выполняют код ниже, затем в первом — COMMIT, во втором — ROLLBACK. Других изменений настройки нет. Что покажет SHOW work_mem в каждом сеансе?
```
BEGIN;
SET work_mem = ''32MB'';
SET LOCAL work_mem = ''64MB'';
```'),
        ('question', 'Клиент psql запущен на ноутбуке и подключён к удалённому серверу PostgreSQL. Где функция SELECT pg_read_file(''postgresql.auto.conf''); ищет файл? Файл существует, необходимые права на чтение есть.', NULL, NULL, NULL, 'psql на ноутбуке подключён к удалённому серверу PostgreSQL. Файл существует, права на чтение есть. Где сервер ищет файл при выполнении запроса?
```
SELECT pg_read_file(''postgresql.auto.conf'');
```'),
        ('question', 'Что означает свойство транзакций «изоляция»?', NULL, NULL, NULL, 'Приложение запускает две транзакции для работы с одними данными. Что гарантирует свойство изоляции?'),
        ('question', 'От имени какой роли подключится psql, если роль не задана ни одним способом: ни ключом -U, ни аргументом, ни строкой подключения, ни переменными окружения, ни сервисом?', NULL, NULL, NULL, 'Пользователь ОС student запускает psql. Имя роли не задано ни в параметрах подключения, ни в окружении или сервисе. От имени какой роли psql попытается подключиться?'),
        ('question', 'В репозитории вашей версии Ubuntu есть PostgreSQL 14, а нужен 16. Как установить его по рекомендации postgresql.org?', NULL, NULL, NULL, 'В репозитории вашего выпуска Ubuntu есть PostgreSQL 14, а нужен 16 с установкой и обновлениями через apt. Как подключить официальный источник пакетов?'),
        ('question', 'Выполнены команды BEGIN; DROP TABLE t; ROLLBACK; Что будет с таблицей t?', NULL, NULL, NULL, 'Постоянная таблица t существует и содержит строки. Команды BEGIN; DROP TABLE t; ROLLBACK; выполнены успешно. В каком состоянии останется t?'),
        ('question', 'В одной транзакции выполнены CREATE TABLE a (x int); ALTER TABLE t ADD COLUMN c int; TRUNCATE t; затем ROLLBACK. Что верно после отката?', NULL, NULL, NULL, 'Таблица t содержит строки и не имеет столбца c; таблицы a нет. Все команды ниже выполнены успешно в одном явном блоке:
```
BEGIN;
CREATE TABLE a (x int);
ALTER TABLE t ADD COLUMN c int;
TRUNCATE t;
ROLLBACK;
```
Что верно после ROLLBACK?'),
        ('option', 'Нужно инициализировать пустой кластер, без копирования существующего. Какая утилита сама создаст его системные базы и конфигурационные файлы?', 'pg_basebackup', NULL, 'Делает резервную копию работающего кластера.', 'pg_basebackup копирует существующий кластер, а не инициализирует пустой.'),
        ('option', 'От имени какого пользователя ОС нельзя запускать initdb и сервер PostgreSQL?', 'Обычный пользователь ОС', NULL, 'Владельцем может быть любой обычный пользователь ОС.', 'Запускать можно от обычного пользователя ОС; он же должен владеть каталогом данных.'),
        ('explanation', 'От имени какого пользователя ОС нельзя запускать initdb и сервер PostgreSQL?', NULL, NULL, 'Так требует безопасность. Обычно владельцем кластера назначают пользователя postgres.', 'Обе программы отказываются работать от root. Каталог данных должен принадлежать пользователю ОС, от имени которого работает сервер; обычно это postgres.'),
        ('option', 'Как включить контрольные суммы в уже существующем кластере?', 'Остановить сервер и выполнить pg_checksums --enable', 'Остановить штатно и выполнить pg_checksums --enable', NULL, NULL),
        ('explanation', 'Как включить контрольные суммы в уже существующем кластере?', NULL, NULL, 'pg_checksums работает только с остановленным кластером. С ключом --check она проверяет текущее состояние.', 'pg_checksums работает только со штатно остановленным кластером. С ключом --check она проверяет текущее состояние.'),
        ('option', 'Что делает команда \gexec?', 'Выполняет значения результата как команды SQL', NULL, 'Каждое значение результата выполняется как отдельная команда SQL. Удобно, когда запрос генерирует команды, например через format().', 'Каждое значение результата, отличное от NULL, отправляется серверу как команда SQL; NULL пропускаются. Удобно, когда запрос генерирует команды, например через format().'),
        ('explanation', 'Что делает команда \gexec?', NULL, NULL, 'Удобно для генерации команд: SELECT format(...) \gexec.', 'Команда удобна, когда запрос формирует SQL для последующего выполнения. Например: SELECT ''SELECT 1;'' AS cmd \gexec — строка результата содержит готовую команду, и метакоманда отправляет её на выполнение.'),
        ('explanation', 'psql запущен без -X, пути и имена файлов настройки не переопределены. Системный psqlrc и пользовательский ~/.psqlrc существуют и доступны для чтения. Как psql обработает эти файлы?', NULL, NULL, 'psql сначала выполняет системный psqlrc, затем пользовательский ~/.psqlrc: личные настройки могут переопределить общие.', 'Сначала системный файл, затем пользовательский: личные настройки могут переопределить общие. Ключ -X отключает чтение обоих.'),
        ('option', 'В исправных файлах конфигурации один параметр задан несколько раз. Какое из этих назначений имеет приоритет при чтении файлов?', 'Последнее считанное', NULL, 'Действует последнее значение, у остальных строк applied = false.', 'Внутри файлов побеждает последнее прочитанное назначение, у остальных строк applied = false. Действующее значение дополнительно определяют более приоритетные источники и контекст параметра.'),
        ('option', 'В сеансе открыли явную транзакцию и выполнили SET LOCAL. Настройку больше не меняют, ROLLBACK TO не выполняют. До какого момента действует заданное значение?', 'До конца сеанса', NULL, 'Так действует обычная команда SET, если транзакция не будет откачена.', 'Так действует обычный SET: после COMMIT он сохраняется в сеансе, ROLLBACK его отменяет.'),
        ('option', 'В сеансе открыли явную транзакцию и выполнили SET LOCAL. Настройку больше не меняют, ROLLBACK TO не выполняют. До какого момента действует заданное значение?', 'До конца текущей транзакции', NULL, 'По окончании транзакции возвращается прежнее значение.', 'После завершения транзакции действует сеансовое значение параметра; при сочетании SET и SET LOCAL оно зависит от COMMIT или ROLLBACK.'),
        ('option', 'Приложению на C нужна клиентская библиотека из стандартной поставки PostgreSQL для подключения и отправки запросов. Что выбрать?', 'JDBC', 'pgJDBC', 'Драйвер для Java реализует протокол самостоятельно, без libpq.', 'pgJDBC — драйвер PostgreSQL для Java, он реализует протокол сам, без libpq.'),
        ('option', 'Транзакция перевода денег меняет два баланса. Какую гарантию её итоговому результату даёт атомарность?', 'Транзакция выполняется целиком или никак', 'Изменения фиксируются целиком либо отменяются', NULL, NULL),
        ('option', 'Транзакция перевода денег меняет два баланса. Какую гарантию её итоговому результату даёт атомарность?', 'Параллельные транзакции не влияют друг на друга', NULL, 'Это изоляция.', 'Это слишком сильное описание изоляции: она ограничивает видимость изменений и допустимые аномалии, но не исключает любое влияние транзакций друг на друга.'),
        ('explanation', 'В какой области оперативной памяти хранятся разобранные запросы, состояние курсоров и рабочие буферы непараллельной сортировки?', NULL, NULL, 'Разобранные запросы, состояние курсоров и память обычных сортировок хранятся в локальной памяти обслуживающего процесса. Параллельные операции могут дополнительно использовать разделяемые структуры.', 'Разобранные запросы, состояние курсоров и память обычных сортировок хранятся в локальной памяти обслуживающего процесса. При нехватке рабочей памяти сортировка может записывать данные во временные файлы; параллельные операции дополнительно используют разделяемые структуры.'),
        ('option', 'В какой ситуации пул соединений, например pgBouncer, поможет сократить затраты на создание backend-процессов?', 'Когда клиентов много или они часто переподключаются', 'Когда много клиентов часто открывают короткие соединения', NULL, NULL),
        ('option', 'В какой ситуации пул соединений, например pgBouncer, поможет сократить затраты на создание backend-процессов?', 'Чтобы ускорить выполнение одного тяжёлого запроса', 'Когда один постоянный клиент выполняет тяжёлую сортировку', 'Пул не ускоряет отдельный запрос.', 'Пул переиспользует соединения, а не меняет алгоритм сортировки. У одного постоянного клиента нет частых повторных подключений, на которых достигается выигрыш.'),
        ('option', 'В какой ситуации пул соединений, например pgBouncer, поможет сократить затраты на создание backend-процессов?', 'Чтобы заменить репликацию между серверами', 'Когда существующие соединения ждут освобождения строк', 'Репликация решает другую задачу.', 'Ожидание блокировок строк пул не устраняет: его причина в конфликтующих транзакциях.'),
        ('option', 'В какой ситуации пул соединений, например pgBouncer, поможет сократить затраты на создание backend-процессов?', 'Чтобы шифровать файлы таблиц на сервере', 'Когда один долгий запрос читает таблицу целиком', 'Пул соединений не шифрует данные на диске: для этого служат средства файловой системы или хранилища.', 'Объём чтения одного запроса от пула не зависит.'),
        ('option', 'Допишите PROMPT1, чтобы перед именем базы появились имя пользователя сеанса и знак @; признаки состояния подключения и транзакции сохраните:
```
\set PROMPT1 ''___%/%R%x%# ''
```', '`%n@`', NULL, 'Имя пользователя текущего сеанса; окончание =# будет у суперпользователя вне транзакции.', '%n показывает пользователя сеанса. SET ROLE меняет текущую роль, но не эту подстановку; SET SESSION AUTHORIZATION может изменить пользователя сеанса.'),
        ('option', 'Допишите вызов, чтобы значение действовало только до конца транзакции:
```
SELECT set_config(''work_mem'', ''32MB'', ___);
```', '`false`', NULL, 'Значение будет действовать до конца сеанса, если транзакция не будет откачена.', 'При false изменение сохраняется в сеансе после COMMIT, а при ROLLBACK отменяется.'),
        ('explanation', 'Какие из перечисленных свойств транзакций в первую очередь обеспечивает многоверсионность?', NULL, NULL, 'Многоверсионность обеспечивает изоляцию (снимки данных) и атомарность (версии строк прерванной транзакции остаются невидимыми); долговечность обеспечивает журнал предзаписи. В курсе сказано, что многоверсионность обеспечивает первые три свойства ACID, включая согласованность: каждая транзакция видит согласованный снимок данных. Соблюдение ограничений целостности обеспечивают сами ограничения.', 'Снимки определяют видимость изменений, а статусы транзакций позволяют не считать действующими версии прерванных транзакций. Это участвует в обеспечении изоляции и атомарности. Соблюдение ограничений и бизнес-инвариантов — отдельная задача; долговечность опирается на WAL.'),
        ('option', 'Почему для сборки неизменённых исходников из Git нужны Flex и Bison, а из официального релизного архива PostgreSQL 16 — нет?', 'В архиве уже есть сгенерированные ими файлы на C', 'В релизном архиве уже есть сгенерированные ими файлы на C', NULL, NULL),
        ('option', 'Вы используете типичный управляемый PostgreSQL у облачного провайдера, без доступа к ОС сервера. Какие два утверждения об администрировании верны?', 'Администратор получает полный доступ к экземпляру', 'Права прикладных пользователей на таблицы назначает провайдер', 'Нет. В управляемом сервисе провайдер ограничивает административный доступ. При самостоятельной установке PostgreSQL на физическом сервере или виртуальной машине доступ определяет администратор этой системы.', 'В обычной модели DBaaS права в прикладной базе задаёт клиент.'),
        ('option', 'Вы используете типичный управляемый PostgreSQL у облачного провайдера, без доступа к ОС сервера. Какие два утверждения об администрировании верны?', 'Резервное копирование в таком режиме невозможно', 'Индексы под запросы приложения выбирает и создаёт провайдер', 'Нет. Резервное копирование возможно, обычно его делает сам провайдер: автоматические копии и восстановление на момент времени.', 'Выбор индексов под запросы приложения остаётся задачей клиента; сервис может давать средства анализа и рекомендации.'),
        ('option', 'Вы используете типичный управляемый PostgreSQL у облачного провайдера, без доступа к ОС сервера. Какие два утверждения об администрировании верны?', 'Управление ограничено инструментами, которые даёт провайдер', 'Доступные настройки ограничены интерфейсами и правами сервиса', 'Да. Настройки и действия доступны через панель и API провайдера, а на сам сервер зайти нельзя.', 'Настройки и действия доступны через панель, API и права роли, которые даёт сервис; на сам сервер зайти нельзя.'),
        ('option', 'Вы используете типичный управляемый PostgreSQL у облачного провайдера, без доступа к ОС сервера. Какие два утверждения об администрировании верны?', 'Основное администрирование берёт на себя провайдер', 'Провайдер обслуживает инфраструктуру и механизмы резервирования', 'Да. Провайдер занимается серверами, обновлениями, копиями и мониторингом: в этом смысл управляемой базы (managed database).', 'Серверы, обновления, резервные копии и мониторинг — зона провайдера, в этом смысл управляемой базы.'),
        ('explanation', 'Вы используете типичный управляемый PostgreSQL у облачного провайдера, без доступа к ОС сервера. Какие два утверждения об администрировании верны?', NULL, NULL, 'Верные ответы: управление ограничено инструментами провайдера и основное администрирование берёт на себя провайдер. DBaaS (Database as a Service, «база данных как услуга») — это общее название управляемой базы у облачного провайдера, например Amazon RDS или Yandex Managed PostgreSQL. Конкретные названия знать не нужно, важна модель: провайдер отвечает за серверы, обновления, резервные копии и мониторинг, а вы работаете с базой через панель, API и обычное подключение, но без доступа к самому серверу. Если PostgreSQL установлен на вашем собственном сервере или виртуальной машине, всё это администрируете вы.', 'Верные ответы: настройки ограничены интерфейсами и правами сервиса, а инфраструктуру и резервирование обслуживает провайдер. DBaaS (Database as a Service, «база данных как услуга») — общее название управляемой базы у облачного провайдера. Схемы, права прикладных пользователей и оптимизация запросов остаются задачами клиента.'),
        ('option', 'Вы работаете в интерактивном psql, буфер запроса пуст. Какие две команды, введённые отдельно, завершат psql?', '`exit`', NULL, 'Альтернатива \q, как и quit.', 'Альтернатива \q, как и quit, — в интерактивном режиме, на отдельной строке при пустом буфере запроса.'),
        ('option', 'Какие три метакоманды psql предназначены для управления форматом вывода? Нужные аргументы, где они требуются, будут переданы.', '`\pset`', NULL, 'Даёт доступ ко всем настройкам форматирования, без параметров показывает их.', 'Задаёт настройки форматирования, например \pset format csv; без параметров лишь показывает их.'),
        ('option', 'В интерактивном psql включён AUTOCOMMIT. Явная транзакция не открыта, SQL-команды отправляют по одной. Как фиксируются успешно выполненные команды?', 'Каждая команда выполняется в отдельной транзакции и сразу фиксируется', 'Каждая выполняется и фиксируется в своей транзакции', NULL, NULL),
        ('explanation', 'Какие процедурные языки поставляются с исходным кодом PostgreSQL 16, хотя для некоторых нужна отдельная поддержка при сборке?', NULL, NULL, 'PL/pgSQL, PL/Perl и PL/Python поставляются с PostgreSQL; для последних двух нужна соответствующая поддержка сборки. PL/Java — сторонний проект.', 'PL/pgSQL, PL/Perl и PL/Python поставляются с PostgreSQL; для последних двух нужна поддержка при сборке, а в конкретной базе язык ещё нужно создать CREATE EXTENSION. PL/Java — сторонний проект.'),
        ('option', 'Что нужно учитывать приложению, работающему через менеджер пула соединений в режиме пула транзакций (например, PgBouncer)?', 'Нельзя полагаться на сохранение состояния сеанса', 'Состояние сеанса между транзакциями клиента может не сохраниться', NULL, NULL),
        ('option', 'Что нужно учитывать приложению, работающему через менеджер пула соединений в режиме пула транзакций (например, PgBouncer)?', 'Клиенты подключаются напрямую к процессу postmaster', 'Каждая новая транзакция клиента получает прежний серверный сеанс', 'Клиенты подключаются к менеджеру пула.', 'Соединение закрепляется за клиентом только на время транзакции, следующая может попасть в другой backend.'),
        ('option', 'Что нужно учитывать приложению, работающему через менеджер пула соединений в режиме пула транзакций (например, PgBouncer)?', 'Каждому клиенту выделяется свой backend на всё время сеанса', 'Сеансовый SET автоматически действует до конца одной транзакции', 'В режиме пула транзакций backend закрепляется за клиентом только на время транзакции; число серверных процессов определяется лимитами пула.', 'Обычный SET не становится SET LOCAL: он остаётся в серверном сеансе и может достаться другому клиенту.'),
        ('option', 'Что нужно учитывать приложению, работающему через менеджер пула соединений в режиме пула транзакций (например, PgBouncer)?', 'Транзакции через такой пул не поддерживаются вовсе', 'Пул переносит временные таблицы клиента в следующий серверный сеанс', 'Нет. В режиме пула транзакций обычные транзакции работают: соединение закрепляется за клиентом до их завершения.', 'Временные таблицы принадлежат backend и в другой сеанс автоматически не переносятся.'),
        ('option', 'Расчёт нужно выполнять на сервере и вызывать из выражения SELECT с аргументами. Какой объект для этого создать?', 'Именованная подпрограмма на сервере, вызываемая из SQL', 'Пользовательскую функцию', 'Функция создаётся в базе; её аргументы и тип результата описываются при объявлении.', 'Функция вызывается в выражении SELECT, принимает аргументы и возвращает результат.'),
        ('option', 'Расчёт нужно выполнять на сервере и вызывать из выражения SELECT с аргументами. Какой объект для этого создать?', 'Сохранённая копия всех строк таблицы на момент резервного копирования', 'Процедуру с выходным параметром', 'Это описание копии данных, а не подпрограммы.', 'Процедуру вызывают командой CALL, а не в выражении SELECT.'),
        ('option', 'Расчёт нужно выполнять на сервере и вызывать из выражения SELECT с аргументами. Какой объект для этого создать?', 'Параметр конфигурации, действующий до конца транзакции', 'Триггерную функцию для таблицы', 'Параметры управляют работой сервера и не являются функциями.', 'Триггерную функцию вызывает механизм триггеров, напрямую в SELECT её не используют.'),
        ('option', 'Расчёт нужно выполнять на сервере и вызывать из выражения SELECT с аргументами. Какой объект для этого создать?', 'Любая команда операционной системы, запускающая сервер', 'Подготовленный оператор PREPARE', 'Серверные утилиты ОС и функции базы — разные объекты.', 'Подготовленный оператор запускают командой EXECUTE, в выражение SELECT он не встраивается.'),
        ('option', 'Есть функция app.add_tax(numeric), возвращающая numeric. Что можно сказать о запросе SELECT app.add_tax(100); без чтения тела функции?', 'Переименовывает аргумент этой функции в 100', 'Вызывает app.add_tax без передачи аргумента', '100 — передаваемое значение, а не новое имя аргумента.', 'Аргумент передан: это значение 100 в скобках.'),
        ('option', 'Есть функция app.add_tax(numeric), возвращающая numeric. Что можно сказать о запросе SELECT app.add_tax(100); без чтения тела функции?', 'Добавляет 100 строк в таблицу с именем app', 'Сохраняет вызов app.add_tax для последующего EXECUTE', 'app здесь имя схемы; действие определяется телом функции.', 'Этот SELECT выполняет вызов. Подготовленный оператор создаёт PREPARE, а запускает EXECUTE.'),
        ('option', 'Есть функция app.add_tax(numeric), возвращающая numeric. Что можно сказать о запросе SELECT app.add_tax(100); без чтения тела функции?', 'Создаёт новую функцию с именем add_tax в app', 'Вызывает функцию app из схемы с именем add_tax', 'Функции создаёт CREATE FUNCTION.', 'До точки указана схема app, после — имя функции add_tax.'),
        ('option', 'Есть функция app.add_tax(numeric), возвращающая numeric. Что можно сказать о запросе SELECT app.add_tax(100); без чтения тела функции?', 'Вызывает функцию с аргументом 100', 'Вызывает app.add_tax с одним аргументом 100', NULL, NULL),
        ('option', 'Объявляете функцию для вызова из SQL. Какие две формы результата можно задать? Возврат ссылок на курсоры не рассматриваем.', 'Два независимых набора строк за один вызов', 'Несколько отдельных результирующих таблиц одного SQL-вызова', NULL, NULL),
        ('option', 'Объявляете функцию для вызова из SQL. Какие две формы результата можно задать? Возврат ссылок на курсоры не рассматриваем.', 'Ровно одну строку: наборы строк запрещены', 'Таблицу с новой структурой столбцов в каждой возвращённой строке', 'RETURNS SETOF и RETURNS TABLE позволяют возвращать наборы.', 'Все строки набора имеют одну структуру, заданную объявлением или выводимую при вызове.'),
        ('option', 'Объявляете функцию для вызова из SQL. Какие две формы результата можно задать? Возврат ссылок на курсоры не рассматриваем.', 'Все пользовательские функции PostgreSQL обязаны возвращать boolean', 'Результат без объявленного или выводимого PostgreSQL типа', 'Тип результата задаётся объявлением функции и не ограничен boolean.', 'Тип результата должен быть определён. Для функции, возвращающей record без OUT-параметров, столбцы задают в запросе; при OUT или RETURNS TABLE структура описана объявлением.'),
        ('option', 'Объявляете функцию для вызова из SQL. Какие две формы результата можно задать? Возврат ссылок на курсоры не рассматриваем.', 'Одно значение, например integer или text', 'Одно значение объявленного типа, например integer или text', NULL, NULL),
        ('option', 'Объявляете функцию для вызова из SQL. Какие две формы результата можно задать? Возврат ссылок на курсоры не рассматриваем.', 'Набор строк, например через RETURNS TABLE', 'Один набор строк, например объявленный через RETURNS TABLE', NULL, NULL),
        ('explanation', 'Объявляете функцию для вызова из SQL. Какие две формы результата можно задать? Возврат ссылок на курсоры не рассматриваем.', NULL, NULL, 'Объявление функции определяет форму результата. Это может быть скалярное значение, составное значение или набор строк.', 'Объявление функции определяет форму результата: скалярное значение, составное значение или набор строк. Ссылки на несколько курсоров — отдельный приём, вопрос его не рассматривает.'),
        ('option', 'Что такое процедура, создаваемая командой CREATE PROCEDURE?', 'Обычное представление, которое обязательно хранит строки на диске', 'Функция для вызова выражением внутри SELECT', 'Представление и процедура имеют разное назначение.', 'Это функция; процедуру нельзя вызвать как выражение SELECT.'),
        ('option', 'Что такое процедура, создаваемая командой CREATE PROCEDURE?', 'Синоним функции, которую вызывают внутри SELECT', 'Подготовленный оператор для запуска через EXECUTE', 'Для процедуры используется CALL, а не вызов как выражения SELECT.', 'Подготовленный оператор создаёт PREPARE, а не CREATE PROCEDURE.'),
        ('option', 'Что такое процедура, создаваемая командой CREATE PROCEDURE?', 'Подпрограмма для выполнения действий, вызываемая CALL', 'Подпрограмма для выполнения действий через CALL', NULL, NULL),
        ('option', 'Что такое процедура, создаваемая командой CREATE PROCEDURE?', 'Фоновый процесс, автоматически создаваемый для каждой таблицы', 'Триггерная функция для привязки через CREATE TRIGGER', 'Определение процедуры не создаёт постоянно работающий процесс.', 'Триггерную функцию создают CREATE FUNCTION с RETURNS trigger.'),
        ('option', 'Для чего в базе данных нужен индекс?', 'Для хранения резервной копии строк таблицы', 'Для хранения резервной копии данных таблицы', NULL, NULL),
        ('option', 'Для чего в базе данных нужен индекс?', 'Для ускорения записи новых строк в таблицу', 'Для накопления вставок перед записью в таблицу', 'Наоборот, каждый индекс замедляет запись: его тоже нужно обновлять.', 'Индекс не является промежуточным буфером вставок. Он требует обслуживания и может увеличить стоимость изменений, но может ускорить поиск изменяемых строк. HOT позволяет избежать новых записей в несуммирующих индексах; суммирующие, например BRIN, могут обновляться.'),
        ('option', 'Для чего в базе данных нужен индекс?', 'Как дополнительный путь доступа к строкам', 'Для поиска строк без полного просмотра таблицы', 'Индекс — дополнительный путь доступа, который может ускорить поиск нужных строк: подходящий индекс позволяет не просматривать всю таблицу.', 'Подходящий индекс позволяет найти нужные строки, не просматривая всю таблицу; будет ли он использован, зависит от запроса.'),
        ('option', 'Для чего в базе данных нужен индекс?', 'Для сжатия данных таблицы на диске', 'Для сжатия строк таблицы в её файлах на диске', NULL, NULL),
        ('option', 'На таблице users успешно создан индекс:
```
CREATE UNIQUE INDEX users_email_uq ON users(email);
```
Строка с email = ''user@example.org'' уже зафиксирована и другими транзакциями не изменяется. Триггеров нет. Что произойдёт при INSERT ещё одной строки с таким email, без ON CONFLICT?', 'Новая строка автоматически заменит существующую', 'Вставка пройдёт, новая строка заменит прежнюю', NULL, NULL),
        ('option', 'На таблице users успешно создан индекс:
```
CREATE UNIQUE INDEX users_email_uq ON users(email);
```
Строка с email = ''user@example.org'' уже зафиксирована и другими транзакциями не изменяется. Триггеров нет. Что произойдёт при INSERT ещё одной строки с таким email, без ON CONFLICT?', 'Индекс будет автоматически удалён сервером', 'Вставка будет пропущена без ошибки, прежняя строка сохранится', 'Конфликт данных не удаляет индекс.', 'Без ON CONFLICT DO NOTHING конфликт не игнорируется.'),
        ('option', 'На таблице users успешно создан индекс:
```
CREATE UNIQUE INDEX users_email_uq ON users(email);
```
Строка с email = ''user@example.org'' уже зафиксирована и другими транзакциями не изменяется. Триггеров нет. Что произойдёт при INSERT ещё одной строки с таким email, без ON CONFLICT?', 'Вставка будет отклонена с ошибкой уникальности', 'Вставка завершится ошибкой, прежняя строка сохранится', 'Уникальный индекс не допускает одинаковые ненулевые ключи.', 'Уникальный индекс не допускает одинаковые ненулевые ключи: вставка отменяется, прежняя строка не меняется.'),
        ('option', 'На таблице users успешно создан индекс:
```
CREATE UNIQUE INDEX users_email_uq ON users(email);
```
Строка с email = ''user@example.org'' уже зафиксирована и другими транзакциями не изменяется. Триггеров нет. Что произойдёт при INSERT ещё одной строки с таким email, без ON CONFLICT?', 'Дубликат будет разрешён до следующего VACUUM', 'Дубликат появится, а уникальность проверится при COMMIT', 'Проверка уникальности не откладывается до очистки.', 'У индекса, созданного CREATE UNIQUE INDEX, проверка не откладывается до COMMIT.'),
        ('option', 'Какие затраты нужно учитывать при добавлении индексов к активно изменяемой таблице?', 'Индексы делают любую запись быстрее, потому что таблица больше не изменяется', 'После каждого COMMIT требуется полная перестройка индексов', 'Таблица продолжает изменяться, а индексы могут добавлять работу.', 'Обычный COMMIT не требует перестройки индексов.'),
        ('option', 'Какие затраты нужно учитывать при добавлении индексов к активно изменяемой таблице?', 'Вставки и часть других изменений требуют обслуживания индексов', 'Вставки и часть обновлений требуют обслуживания индексов', 'Ускорение чтения может сопровождаться дополнительной работой при записи.', 'Индексы требуют обслуживания при вставках и обновлениях. При UPDATE без HOT новая версия требует записей и в индексах с неизменившимися ключами; в частичный индекс попадают строки, удовлетворяющие его условию.'),
        ('option', 'Какие затраты нужно учитывать при добавлении индексов к активно изменяемой таблице?', 'После создания индекса все строки таблицы обязательно помещаются в оперативную память', 'Файл таблицы растёт на суммарный размер её индексов', 'Индекс не гарантирует размещение всей таблицы в памяти.', 'Индекс хранится в своих файлах, отдельно от таблицы.'),
        ('option', 'Какие затраты нужно учитывать при добавлении индексов к активно изменяемой таблице?', 'Индексы занимают дополнительное место на диске', 'Для хранения индексов требуется дополнительное место на диске', NULL, NULL),
        ('option', 'Какие затраты нужно учитывать при добавлении индексов к активно изменяемой таблице?', 'Индекс автоматически избавляет таблицу от необходимости VACUUM', 'VACUUM отдельно читает таблицу для каждого её индекса', 'Наличие индекса не отменяет очистку таблицы и индексов.', 'Отдельный проход по таблице для каждого индекса не нужен: найденные мёртвые версии используются для очистки всех индексов; при нехватке памяти очистка может идти несколькими циклами.'),
        ('option', 'Какие из этих индексов можно создать в PostgreSQL 16?', 'Индекс по выражению, например lower(email)', 'Индекс по выражению, например по lower(email)', NULL, NULL),
        ('option', 'Какие из этих индексов можно создать в PostgreSQL 16?', 'Частичный индекс только по строкам, удовлетворяющим условию WHERE', 'Частичный индекс с условием WHERE по строкам таблицы', NULL, NULL),
        ('option', 'Какие из этих индексов можно создать в PostgreSQL 16?', 'Только индексы по одному столбцу, выражения и условия запрещены', 'Индекс по выражению с вызовом random() для каждой строки', 'Поддерживаются и выражения, и частичные, и многоколоночные индексы.', 'random() не IMMUTABLE, а в определении индекса допустимы только IMMUTABLE-функции.'),
        ('option', 'Какие из этих индексов можно создать в PostgreSQL 16?', 'Индекс, объединяющий строки таблиц из двух разных баз кластера', 'Частичный индекс с подзапросом к другой таблице в WHERE', 'Обычный индекс строится для конкретной таблицы, а не между базами.', 'Подзапросы в условии частичного индекса запрещены.'),
        ('option', 'Какие из этих индексов можно создать в PostgreSQL 16?', 'Индекс, автоматически обновляющий материализованное представление при каждой записи', 'Индекс по выражению с агрегатной функцией sum', 'Создание индекса не добавляет такой механизм обновления.', 'Агрегатные функции в индексном выражении недопустимы.'),
        ('explanation', 'Клиент впервые готовит и выполняет запрос с параметрами по расширенному протоколу. В каком порядке он отправляет сообщения Parse, Bind и Execute?', NULL, NULL, 'При повторном выполнении того же оператора Parse не нужен: достаточно Bind и Execute. Портал — подготовленный оператор с привязанными значениями параметров, готовый к выполнению; в SQL ему соответствует курсор. Execute может получать строки порциями. Сообщение Sync завершает цикл: после него сервер фиксирует неявную транзакцию.', 'При повторном выполнении того же оператора Parse не нужен: достаточно Bind и Execute. Портал — подготовленный оператор с привязанными значениями параметров, готовый к выполнению; в SQL ему соответствует курсор. Execute может получать строки порциями. Sync завершает цикл обмена: вне явного блока транзакции сервер фиксирует успешную неявную транзакцию или откатывает её после ошибки; явный блок Sync не завершает.'),
        ('option', 'Приложение запускает две транзакции для работы с одними данными. Что гарантирует свойство изоляции?', 'Зафиксированные данные не теряются даже в случае сбоя', 'Сохранение зафиксированных данных после сбоя', NULL, NULL),
        ('option', 'Приложение запускает две транзакции для работы с одними данными. Что гарантирует свойство изоляции?', 'Транзакции выполняются последовательно, одна за другой', 'Последовательный запуск транзакций без пересечения во времени', NULL, NULL),
        ('option', 'Приложение запускает две транзакции для работы с одними данными. Что гарантирует свойство изоляции?', 'Транзакции влияют друг на друга в пределах уровня изоляции', 'Ограничение видимости чужих изменений и допустимых аномалий', 'Параллельно выполняемые транзакции влияют друг на друга только в пределах, которые допускает их уровень изоляции. В PostgreSQL для этого служат снимки данных и блокировки, а на уровне Serializable — ещё и отслеживание зависимостей.', 'Уровень изоляции определяет, какие чужие изменения видны транзакции и какие аномалии допустимы; в PostgreSQL для этого служат снимки, блокировки, а на Serializable — ещё и отслеживание зависимостей.'),
        ('option', 'Приложение запускает две транзакции для работы с одними данными. Что гарантирует свойство изоляции?', 'Транзакция выполняется полностью или не выполняется вовсе', 'Фиксацию всех изменений транзакции либо их полный откат', NULL, NULL),
        ('option', 'В psql с настройками по умолчанию открыта транзакция; после SAVEPOINT s очередная команда завершилась ошибкой. Что верно?', 'Обычные команды отклоняются до отката транзакции или к точке', 'Обычные SQL-команды отклоняются до ROLLBACK или ROLLBACK TO s', NULL, NULL),
        ('explanation', 'В psql с настройками по умолчанию открыта транзакция; после SAVEPOINT s очередная команда завершилась ошибкой. Что верно?', NULL, NULL, 'Точка сохранения позволяет отменить только ошибочную часть транзакции, а не всю её.', 'ROLLBACK TO s отменяет все изменения после s, включая успешные команды, и позволяет продолжить транзакцию. Изменения до s остаются незафиксированными до COMMIT.'),
        ('option', 'Допишите запрос, чтобы получить список параметров, изменение которых вступает в силу только после перезапуска сервера:
```
SELECT name FROM pg_settings WHERE context = ''___'';
```', '`postmaster`', NULL, 'Такие параметры читает только postmaster при запуске, например shared_buffers и max_connections.', 'Новое значение такого параметра применяется при запуске экземпляра. Перечитывание конфигурации обнаружит изменение и выставит pending_restart, но применить его без перезапуска не может.'),
        ('explanation', 'Какие столбцы pg_settings показывают, из какого файла и с какой строки взято текущее значение параметра?', NULL, NULL, 'Если параметр задан в нескольких файлах, столбцы показывают действующее значение, то есть прочитанное последним.', 'Если текущее значение получено из файла, sourcefile и sourceline указывают этот файл и строку. Для других источников, а также без права просмотра эти поля равны NULL. Само значение находится в setting.'),
        ('option', 'Пользователь ОС student запускает psql. Имя роли не задано ни в параметрах подключения, ни в окружении или сервисе. От имени какой роли psql попытается подключиться?', 'Роли с именем пользователя ОС, запустившего psql', 'Роли student — по имени пользователя ОС', 'Используется имя пользователя ОС. Подключение возможно, если такая роль существует и имеет нужные права; иначе будет ошибка «роль не существует».', 'По умолчанию используется имя пользователя ОС. Отсутствие роли, запрет входа или ошибка аутентификации могут помешать подключению; причину покажет сообщение сервера.'),
        ('option', 'Что верно о метакоманде \g в psql?', 'SELECT ... \g | cat -n передаёт вывод запроса команде ОС через конвейер', 'SELECT 1 \g | cat -n передаёт вывод запроса команде ОС через конвейер', NULL, NULL),
        ('option', 'Что верно о метакоманде \g в psql?', '\g (format=unaligned) меняет формат вывода для всех следующих запросов', '\g (format=unaligned) меняет формат всех следующих результатов', NULL, NULL),
        ('option', 'Что верно о метакоманде \g в psql?', 'SELECT ... \g (format=unaligned tuples_only=on) файл задаёт формат вывода только для этого запроса', 'SELECT 1 \g (format=unaligned) result.txt задаёт формат только для этого запроса', NULL, NULL),
        ('option', 'Что верно о метакоманде \g в psql?', 'SELECT ... \g файл записывает вывод этого запроса в файл', 'SELECT 1 \g result.txt записывает вывод этого запроса в файл', NULL, NULL),
        ('explanation', 'Что верно о метакоманде \g в psql?', NULL, NULL, 'Такие приёмы удобны в скриптах: результат можно сразу передать программе ОС или сохранить в файл без заголовков и выравнивания.', 'Результат запроса можно передать программе ОС или сохранить в файл. Параметры в скобках после \g меняют формат для одного выполнения; убрать заголовки и итоговую строку можно параметром tuples_only=on.'),
        ('option', 'Как узнать, включены ли контрольные суммы страниц в кластере?', 'Остановить сервер и выполнить `pg_checksums --check`', 'После штатной остановки изучить вывод `pg_checksums --check`', 'Проверка — режим по умолчанию, работает только на корректно остановленном сервере.', 'Проверка — режим по умолчанию. При отключённых суммах утилита сообщает об этом; одного кода возврата без текста сообщения недостаточно.'),
        ('option', 'В репозитории вашего выпуска Ubuntu есть PostgreSQL 14, а нужен 16 с установкой и обновлениями через apt. Как подключить официальный источник пакетов?', 'Собрать PostgreSQL 16 из исходных кодов', NULL, 'Можно, но тогда установка и обновления на вас; в обычном случае сборка не нужна.', 'Сборка из исходников возможна, но не даёт установки и обновлений пакетами apt.'),
        ('option', 'Постоянная таблица t существует и содержит строки. Команды BEGIN; DROP TABLE t; ROLLBACK; выполнены успешно. В каком состоянии останется t?', 'Таблица t останется на месте со всеми строками: DROP TABLE откатывается', 'Таблица сохранится с прежней структурой и всеми строками', NULL, NULL),
        ('option', 'Постоянная таблица t существует и содержит строки. Команды BEGIN; DROP TABLE t; ROLLBACK; выполнены успешно. В каком состоянии останется t?', 'Таблица t останется пустой: ROLLBACK восстановит её структуру без строк', 'Таблица сохранится со структурой, но строки будут потеряны', NULL, NULL),
        ('option', 'Постоянная таблица t существует и содержит строки. Команды BEGIN; DROP TABLE t; ROLLBACK; выполнены успешно. В каком состоянии останется t?', 'Таблица t будет удалена, потому что DROP TABLE фиксируется сразу при выполнении', 'Таблица останется удалённой после завершения ROLLBACK', NULL, NULL),
        ('option', 'Постоянная таблица t существует и содержит строки. Команды BEGIN; DROP TABLE t; ROLLBACK; выполнены успешно. В каком состоянии останется t?', 'ROLLBACK завершится ошибкой, потому что DDL нельзя отменять внутри транзакции', 'Таблица сохранится, но при отключении сеанса будет удалена', 'ROLLBACK отменяет и команды DDL, никакой ошибки нет.', 'Откат восстанавливает постоянную таблицу; её существование не ограничено сеансом.'),
        ('explanation', 'Таблица t содержит строки и не имеет столбца c; таблицы a нет. Все команды ниже выполнены успешно в одном явном блоке:
```
BEGIN;
CREATE TABLE a (x int);
ALTER TABLE t ADD COLUMN c int;
TRUNCATE t;
ROLLBACK;
```
Что верно после ROLLBACK?', NULL, NULL, 'Команды DDL, кроме немногих исключений (например, CREATE DATABASE и VACUUM), выполняются внутри обычной транзакции и откатываются вместе с остальными изменениями. Проверка: BEGIN; CREATE TABLE a (x int); ROLLBACK; SELECT to_regclass(''a''); — результат NULL.', 'CREATE TABLE, эта форма ALTER TABLE и TRUNCATE транзакционны: полный откат отменяет их результат. Не все команды разрешены внутри блока; например, CREATE DATABASE и VACUUM выполняют отдельно.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
